// Is this Slack message a client's ticket (or a follow-up in a ticket's thread)? If yes, pull out what the next
// steps need. Anything else returns nothing, which ends the run quietly: our bot's own posts,
// edits, deletions, join notices and chat in #support-queue. Messages from the agency's own staff end at the next
// step, which checks the staff list in the database.
const s = $('Settings').first().json;
for (const [name, value] of Object.entries(s)) {
  if (!String(value ?? '').trim() || String(value).startsWith('PASTE_')) {
    throw new Error(`Settings: ${name} is not filled in. No ticket was made.`);
  }
}
const e = $('Slack message').first().json;

// A plain message, one with a file, or a thread reply also sent to the channel.
const CLIENT_SUBTYPES = [undefined, 'file_share', 'thread_broadcast'];
if (e.type !== 'message') return [];
if (e.bot_id || e.app_id) return []; // our bot, or any other app: never a ticket
if (!CLIENT_SUBTYPES.includes(e.subtype)) return []; // edits, deletions, joins, channel notices
if (!e.user) return [];
if (e.channel === s.support_queue_channel) return [];

return [{
  json: {
    channel_id: e.channel,
    thread_ts: e.thread_ts ?? e.ts, // a reply belongs to its thread; a new message starts one
    message_key: `${e.channel}:${e.ts}`, // unique per Slack message (the trigger doesn't pass Slack's event ID)
    slack_user: e.user,
    text: (e.text ?? '').trim(), // may be empty (a screenshot only): the agent then hands it to a person
    has_files: Array.isArray(e.files) && e.files.length > 0,
  },
}];

