// Turn the saved draft into its card for #support-queue. Everything the client or the AI wrote is escaped, so text
// like <!channel> or a disguised link shows as plain text: it can't ping everyone or hide where a link goes.
const s = $('Settings').first().json;
const row = $input.first().json; // the saved draft: draft_id, ticket_id, status, draft
const client = $('Find client').first().json;
const msg = $('Read message').first().json;
const ticket = $('Save message').first().json;
// Why there's no draft, in plain words for the support team; the exact error stays in the database.
const why = (err) => {
  const e = String(err ?? '');
  if (/ENOTFOUND|ECONNREFUSED|ECONNRESET|EAI_AGAIN/.test(e)) return "the agent isn't running";
  if (/timeout|ECONNABORTED|ETIMEDOUT/i.test(e)) return 'the agent took longer than 90 seconds';
  const tooLong = e.match(/ticket too long: (\d+) characters, limit (\d+)/);
  if (tooLong) return `the message is too long for the agent (${Number(tooLong[1]).toLocaleString('en-US')} characters; it takes up to ${Number(tooLong[2]).toLocaleString('en-US')})`;
  if (/ai spending limit reached/.test(e)) return "the AI account's spending limit or prepaid credit ran out (see #support-alerts)";
  if (/^503\b/.test(e)) return 'the agent was busy with other tickets';
  if (/^401\b/.test(e)) return "the agent refused n8n's key (check the Agent API login in n8n)";
  return 'the agent ran into an error (details in n8n)';
};
// A pause reason as the admin app shows it (admin/clients.py, PAUSE_REASONS).
const PAUSE_LABELS = {
  key_broken: 'Key broken',
  drafts_wrong: 'Drafts going wrong',
  account_changing: 'Account changing',
  privacy_hold: 'Privacy hold',
  client_asked: 'Client asked',
  billing_hold: 'Billing hold',
};
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const MAX = 2900; // Slack allows 3000 characters per section
const cut = (t) => (t.length > MAX ? t.slice(0, MAX - 1) + '…' : t);
const quote = (t) => esc(t).split('\n').map((line) => '> ' + line).join('\n');
const section = (text) => ({ type: 'section', text: { type: 'mrkdwn', text: cut(text) } });
// Only plain https links become clickable; anything else is shown as text.
const safeUrl = (u) => /^https:\/\/[^\s<>|]+$/.test(String(u ?? ''));
const button = (text, actionId, style) => ({
  type: 'button',
  text: { type: 'plain_text', text },
  action_id: actionId,
  value: row.draft_id, // the buttons (Ticket approval workflow) act on this draft only
  ...(style ? { style } : {}),
});

const name = esc(client.display_name);
const threadLink = `${s.slack_workspace_url.replace(/\/+$/, '')}/archives/${msg.channel_id}/p${msg.thread_ts.replace('.', '')}`;
const header = `*🎫 ${name}*`;
const clientWrote = `*Client wrote:*\n${ticket.full_text.trim() ? quote(ticket.full_text) : '_No text: a file or screenshot only._'}`;

let text;
let blocks;
if (row.status === 'agent_unavailable') {
  text = `Agent unavailable for ${name}: needs a person`;
  blocks = [
    section(`${header} · <${threadLink}|open the client's thread>`),
    section(`:rotating_light: *Agent unavailable, needs a person.* No draft was made because ${why(row.draft?.error)}. Please answer the client yourself.`),
    section(clientWrote),
    { type: 'actions', block_id: 'draft_actions', elements: [button('Take over', 'take_over', 'primary')] },
  ];
} else if (row.status === 'limit_reached') {
  text = `Limit reached for ${name}: needs a person`;
  blocks = [
    section(`${header} · <${threadLink}|open the client's thread>`),
    section(`:no_entry: *Limit reached, needs a person.* ${name} has had ${esc(row.draft?.limit)} drafts in the last 60 minutes, so no draft was made (no AI call). Please answer the client yourself.`),
    section(clientWrote),
    { type: 'actions', block_id: 'draft_actions', elements: [button('Take over', 'take_over', 'primary')] },
  ];
} else if (row.status === 'client_paused') {
  const reason = esc(PAUSE_LABELS[row.draft?.paused] ?? row.draft?.paused);
  text = `Paused: answer by hand · ${reason} · ${name}`;
  blocks = [
    section(`${header} · <${threadLink}|open the client's thread>`),
    section(`:double_vertical_bar: *Paused: answer by hand* · ${reason}. ${name} is paused in the admin app, so no draft was made (no AI call). Please answer the client yourself.`),
    section(clientWrote),
    { type: 'actions', block_id: 'draft_actions', elements: [button('Take over', 'take_over', 'primary')] },
  ];
} else {
  const d = row.draft;
  text = `New draft for ${name} (confidence: ${esc(d.confidence)})`;
  blocks = [section(`${header} · confidence: *${esc(d.confidence)}* · <${threadLink}|open the client's thread>`)];
  if (d.needs_person) blocks.push(section(`:warning: *Needs a person:* ${esc(d.needs_person_reason)}`));
  if (d.suspicious_sources?.length) blocks.push(section(`:warning: *A source may have been tampered with:* ${d.suspicious_sources.map(esc).join(' · ')}. It holds a line aimed at the AI, which the draft left out. Please check that source and clean it up (run guide, section 3).`));
  if (d.checks_failed?.length) blocks.push(section(`:no_entry: *Checks failed:* ${d.checks_failed.map(esc).join(' · ')}`));
  blocks.push(section(clientWrote));
  blocks.push(section(`*Reply to send:*\n${quote(d.client_reply)}`));
  blocks.push(section(`*Likely cause:* ${esc(d.likely_cause)}`));
  if (d.fix_steps?.length) blocks.push(section(`*Fix steps:*\n${d.fix_steps.map((x, i) => `${i + 1}. ${esc(x)}`).join('\n')}`));
  if (d.evidence?.length) blocks.push(section(`*Evidence:*\n${d.evidence.map((x) => `• ${esc(x)}`).join('\n')}`));
  if (d.sources?.length) {
    const links = d.sources.map((x) => (safeUrl(x.url) ? `<${x.url}|${esc(x.title)}>` : esc(x.title)));
    blocks.push(section(`*Sources:* ${links.join(' · ')}`));
  }
  // Which lookups the agent made, in order (names only, never what it asked or found), so staff see why it says what it says.
  if (d.checks_ran?.length) {
    // An empty GHL check is not proof that nothing is there (missing access looks the same), so it never says nothing found.
    const SEARCHES = ['search_guides', 'search_ghl_help', 'find_similar_tickets'];
    const how = (c) => (c.result === 'error' ? ' (failed)' : c.result !== 'empty' ? '' : SEARCHES.includes(c.name) ? ' (nothing found)' : ' (came back empty)');
    blocks.push(section(`*Looked up:* ${d.checks_ran.map((c) => esc(String(c.name).replace(/_/g, ' ')) + how(c)).join(' · ')}`));
  }
  blocks = [
    ...blocks,
    {
      type: 'actions',
      block_id: 'draft_actions',
      elements: [button('Approve and send', 'approve', 'primary'), button('Edit', 'edit'), button('Take over', 'take_over')],
    },
  ];
}
return [{ json: { draft_id: row.draft_id, text, blocks: JSON.stringify({ blocks }) } }];
